function aoe4Name(value) {
  return String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

function aoe4GuideHTML(guide) {
  const escape = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paragraph = (heading, text) => '<h2>' + heading + '</h2><p>' + escape(text) + '</p>';
  return '<h1>' + escape(guide.name) + '</h1><p><strong>' + escape(guide.style) + '</strong> · ' + escape(guide.pack) + '</p>' +
    paragraph('À retenir', guide.identity) + '<h2>Build order — ' + escape(guide.build) + '</h2>' +
    '<p>Ouverture d’entraînement · 1 contre 1 terrestre. Les répartitions sont des repères à ajuster aux files de production, à la carte et à la reconnaissance. Nourriture / bois / or / pierre : ressources non dépensées, pas revenus cumulés.</p>' +
    '<table><thead><tr><th scope="col">Étape</th><th scope="col">Actions</th></tr></thead><tbody>' +
    guide.steps.map(([phase, action], index) => '<tr><th scope="row">' + (index + 1) + '. ' + escape(phase) + '</th><td>' + escape(action) + '</td></tr>').join('') + '</tbody></table>' +
    paragraph('Armée à viser', guide.army) + paragraph('Adapter le plan', guide.adapt) + paragraph('Erreurs à éviter', guide.avoid) +
    '<h2>Pour approfondir</h2><p>Fiche relue le 19 novembre 2026. Mécaniques : <a href="https://www.ageofempires.com/civilizations/" target="_blank" rel="noopener noreferrer">civilisations officielles AoE IV</a>. ' +
    'Détails de la civilisation : <a href="https://www.ageofempires.com/games/age-of-empires-iv/civilizations/' + escape(guide.id) + '/" target="_blank" rel="noopener noreferrer">' + escape(guide.name) + '</a>. ' +
    'Pour comparer les ouvertures : <a href="https://www.laylacoach.com/build-orders" target="_blank" rel="noopener noreferrer">répertoire de build orders et auteurs</a>. Les étapes ci-dessus sont une synthèse pédagogique ; les coûts et options affichés dans ta version du jeu priment.</p>';
}

function buildAOE4Civilizations(snapshot, stamp = new Date().toISOString()) {
  const {items = [], folders = [], settings = []} = snapshot;
  if (Number(settings.find(row => row.key === AOE4_GUIDES_SETTING)?.value) >= AOE4_GUIDES_VERSION) return {operations:[]};
  const alive = record => !record.deletedAt && !record.deleted;
  const active = folders.filter(folder => alive(folder) && ['library','memo'].includes(folder.section));
  const byId = new Map(active.map(folder => [folder.id,folder]));
  const ancestors = folder => {
    const result = [], seen = new Set();
    while (folder) {
      if (seen.has(folder.id)) throw new Error('Cycle dans les dossiers AoE IV : ajout annulé.');
      seen.add(folder.id); result.push(folder); folder = byId.get(folder.parentId);
    }
    return result;
  };
  // Validate before preparing any mutation, and do not touch other sections.
  for (const folder of active) ancestors(folder);
  const operations = [];
  const occupied = new Set([...items.map(row=>row.id), ...folders.map(row=>row.id)]);
  const unique = base => { let id = base, suffix = 2; while (occupied.has(id)) id = base + '-' + suffix++; occupied.add(id); return id; };
  const isGames = folder => ['jeux','jeu','games','gaming'].includes(aoe4Name(folder.name));
  const isAOE = folder => /^(aoe\s*(4|iv)?|age of empires\s*(4|iv)?)$/.test(aoe4Name(folder.name));
  // Prefer the user's existing AoE branch, including nested folders and aliases.
  let target = active.find(folder => isAOE(folder) && ancestors(folder).some(isGames));
  let games = target ? ancestors(target).find(isGames) : active.find(folder => isGames(folder) && !folder.parentId);
  if (!games) {
    games = {id:unique('memo-games'),name:'Jeux',section:'library',parentId:null,createdAt:stamp,updatedAt:stamp};
    operations.push({action:'put',store:'folders',record:games});
  }
  if (!target) {
    target = {id:unique('memo-games-aoe4'),name:'AoE IV',section:'library',parentId:games.id,createdAt:stamp,updatedAt:stamp};
    operations.push({action:'put',store:'folders',record:target});
  }
  const inBranch = folderId => folderId === target.id || (byId.has(folderId) && ancestors(byId.get(folderId)).some(folder=>folder.id===target.id));
  const matches = (item, guide) => {
    if (item.aoe4CivilizationId) return item.aoe4CivilizationId === guide.id;
    // Long aliases win over base names (e.g. Jeanne vs French matchup notes).
    const title = ' ' + aoe4Name(item.title) + ' ';
    return [guide.name,...guide.aliases].some(alias => title.includes(' ' + aoe4Name(alias) + ' '));
  };
  for (const guide of AOE4_GUIDES) {
    const candidates = items.filter(item => alive(item) && ['memo','protocol','procedure'].includes(item.type) && inBranch(item.folderId) && matches(item,guide) && AOE4_GUIDES.filter(other=>matches(item,other)).length===1);
    const existing = candidates.find(item=>item.aoe4CivilizationId===guide.id) || candidates[0];
    if (existing && Number(existing.aoe4GuideVersion) >= AOE4_GUIDES_VERSION) continue;
    // Honor previously deleted generated guides; never resurrect them.
    if (!existing && items.some(item=>item.aoe4CivilizationId===guide.id && !alive(item))) continue;
    const content = aoe4GuideHTML(guide) + (existing?.content ? '<h2>Notes déjà présentes</h2>' + existing.content : '');
    const record = existing ? {...existing,content,aoe4CivilizationId:guide.id,aoe4GuideVersion:AOE4_GUIDES_VERSION,updatedAt:stamp} : {
      id:unique('memo-aoe4-'+guide.id),type:'memo',originalType:'memo',documentType:'memo',unifiedDocument:true,unifiedDocumentVersion:2,
      title:guide.name,description:guide.build,folderId:target.id,content,tags:['AoE IV','Civilisation','Build order'],facets:libraryFacets(),favorite:false,attachments:[],commandBlocks:[],createdAt:stamp,updatedAt:stamp,
      aoe4CivilizationId:guide.id,aoe4GuideVersion:AOE4_GUIDES_VERSION
    };
    operations.push({action:'put',store:'items',record});
  }
  operations.push({action:'put',store:'settings',record:{key:AOE4_GUIDES_SETTING,value:AOE4_GUIDES_VERSION}});
  return {operations};
}

