    const allowed=()=>['agents.write','remote.terminal'].every(right=>WolfGuardCloud.can(right)&&(typeof WolfGuardAccess==='undefined'||WolfGuardAccess.can(right)));
    if(automaticRunning||!state.vaultKey||!WolfGuardCloud.hasSession()||!allowed())return;
    const key=state.vaultKey,userId=WolfGuardCloud.currentUser()?.id;
