  label: 'R\u00e9seau',
  match: /^(dns\b|mdns\b|llmnr\b|dhcp|ntp\b|nts\b|bgp\b|ipsec\b|ike\b|l2tp\b|openvpn\b|wireguard\b|pptp\b|capwap\b|vxlan\b|gtp-|netconf\b|gnmi\b|bfd\b|rip|ptp\b|pcp\b|icmp|ospf\b|gre\b|esp\b|ah\b|vrrp\b)/
