      const bsd=/\(([\d.]+)\)\s+at\s+([\da-f]{1,2}(?::[\da-f]{1,2}){5})\s+on\s+(\S+)/i.exec(value)||/^([\da-f:]+(?:%[\w.-]+)?)\s+([\da-f]{1,2}(?::[\da-f]{1,2}){5})\s+(\S+)/i.exec(value);
