    vulnerability: {strategy:'passive',title:'Scan de vulnérabilités',short:'Audit de sécurité',description:'Vérifier les protections et la configuration du poste choisi.',kicker:'AUDIT DU POSTE · LECTURE SEULE',configTitle:'Périmètre de l’audit',context:'Contrôles adaptés à Windows, Linux et macOS',launchLabel:'Lancer l’audit',tabs:['Risques et actions','Tous les contrôles','Évolution']}
