/* js/views/settings.js */
'use strict';

async function saveWorkspaceFromSettings() {
  if (db?.native) {
    await db.flush();
    appNotify('Toutes les modifications sont enregistr\u00e9es dans SQLite.');
    return
  }
  if (workspaceCanWrite()) {
    const ok = await writePortableFile();
    if (ok) appNotify('Bases ITW enregistrées.');
    else if (localServiceAvailable()) appNotify(localWorkspaceError || 'Enregistrement en cours. Réessaie dans un instant.');
    return;
  }
  appNotify('L’écriture directe dans le fichier n’est pas disponible dans ce navigateur.');
}

async function reloadWorkspaceFromSettings() {
  if (workspaceCanWrite() || localServiceAvailable()) {
    await loadPortableFile(true);
    return;
  }
  closeModal();
  openItwFilePicker();
}

function changeWorkspaceFromSettings() {
  if (desktopBridge.available) {
    desktopBridge.call('data.openFolder').catch(error => appNotify(error.message));
    return
  }
  if (localServiceAvailable()) return;
  window.workspaceSearch?.reset();
  closeModal();
  connectedWorkspaceReady = false;
  resetPinUI();
  sessionAccessCode = '';
  state.vaultKey = null;
  portableDirHandle = null;
  portableFileHandle = null;
  portableSectionHandles = new Map();
  clearTimeout(portableSaveTimer);
  portableSavePending = false;
  portableReadOnly = false;
  portableFileName = 'Bases par section';
  updateDataStatus('local');
  $('#app').classList.add('hidden');
  $('#lock').classList.add('hidden');
  $('#connectionGate').classList.remove('hidden');
  $('.connection-actions').classList.remove('hidden');
  $('#connectRequiredBtn').hidden = false;
  $('#connectionHeading').textContent = 'Connecter la base';
  setConnectionStatus('');
}

function interfacePreferenceKey(){return 'wolfguard-interface:'+(typeof WolfGuardCloud!=='undefined'?WolfGuardCloud.currentUser()?.id||'local':'local');}
function applyInterfacePreferences(value){
  if(!value){try{value=JSON.parse(localStorage.getItem(interfacePreferenceKey())||'{}');}catch{value={};}}
  const allowed={theme:['midnight','slate','contrast'],density:['comfortable','compact'],text:['100','110','120'],motion:['system','reduced']};
  const result={};for(const [key,values]of Object.entries(allowed))result[key]=values.includes(value[key])?value[key]:values[0];
  const root=document.documentElement;root.dataset.uiTheme=result.theme;root.dataset.uiDensity=result.density;root.dataset.uiMotion=result.motion;root.style.setProperty('--reading-scale',Number(result.text)/100);
  return result;
}
window.addEventListener('wolfguard-user-changed',()=>applyInterfacePreferences());
applyInterfacePreferences();

